arguments:
{"script":"set -e
[ -d "$HOME/videos" ] || { echo "Directory ~/videos not found" >&2; exit 1; }
find "$HOME/videos" -type d -exec chmod 750 {} +
find "$HOME/videos" -type f -exec chmod 660 {} +
mismatch=$(find "$HOME/videos" \( -type d ! -perm 750 -o -type f ! -perm 660 \) -print -quit)
if [ -z "$mismatch" ]; then echo OK; else find "$HOME/videos" \( -type d ! -perm 750 -o -type f ! -perm 660 \) -ls; fi"}
